import React from "react";
import { motion } from "framer-motion";

const skills = ["Python", "Java", "C", "HTML", "CSS", "JavaScript", "SQL", "UI/UX"];

const Skills = () => {
  return (
    <div className="section">
      <h2>Skills</h2>
      <div className="skills">
        {skills.map((skill, index) => (
          <motion.div key={index} className="skill-card" whileHover={{ scale: 1.2 }}>
            {skill}
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default Skills;
